<script setup lang="ts">
import {onMounted} from 'vue'
import {api} from '../api'
import type {Health,PaperSummary} from '../types/research'
import {useResource} from '../composables/useResource'
import AsyncState from '../components/AsyncState.vue'
import Icon from '../components/Icon.vue'
const {data:health,loading,error,load}=useResource<Health|null>(null)
const {data:papers,load:loadPapers}=useResource<PaperSummary[]>([])
function refresh(){load(()=>api.health());loadPapers(async()=>(await api.papers({page_size:3})).items)}
onMounted(refresh)
const shortcuts=[{path:'/search',icon:'Search',title:'发现相关文献',text:'从研究问题出发，检索学术论文。',n:'01'},{path:'/analysis',icon:'Reading',title:'深入阅读论文',text:'梳理方法与发现，回到原文证据。',n:'02'},{path:'/reviews',icon:'Files',title:'整理研究脉络',text:'比较多篇论文，形成有据可查的综述。',n:'03'}]
</script>
<template><div class="page-heading"><div><div class="eyebrow">YOUR RESEARCH, CONNECTED</div><h1>开始一段有据可循的研究。</h1><p>从发现一篇论文，到厘清一个研究问题。</p></div><RouterLink class="primary-link" to="/search"><Icon name="Plus"/>开始文献检索</RouterLink></div><AsyncState :loading="loading" :error="error" @retry="refresh"><div class="stats-grid"><div v-for="(item,i) in [{label:'我的文献',value:health?.stats?.papers,icon:'Collection',unit:'篇'},{label:'已解析文档',value:health?.stats?.documents,icon:'Document',unit:'份'},{label:'论文分析',value:health?.stats?.analyses,icon:'Reading',unit:'份'},{label:'研究综述',value:health?.stats?.reviews,icon:'Files',unit:'份'}]" :key="i" class="panel stat-card"><div class="flex-between"><span>{{item.label}}</span><Icon :name="item.icon"/></div><div class="stat-value">{{item.value??'—'}}<span>{{item.unit}}</span></div><div class="stat-foot">{{item.value===undefined?'等待服务端提供统计':'当前工作区记录'}}</div></div></div></AsyncState><section class="research-path"><div class="section-heading"><div><span class="eyebrow">RESEARCH WORKFLOW</span><h2>把研究步骤，连成一条线。</h2></div><span class="muted">发现 → 阅读 → 综合</span></div><div class="shortcut-grid"><RouterLink v-for="s in shortcuts" :key="s.path" :to="s.path" class="panel shortcut-card"><div class="flex-between"><span class="shortcut-icon"><Icon :name="s.icon"/></span><span class="path-number">{{s.n}}</span></div><h3>{{s.title}}</h3><p>{{s.text}}</p><span class="shortcut-arrow">进入工作区 <span>↗</span></span></RouterLink></div></section><div class="dashboard-bottom"><section class="panel recent-panel"><div class="panel-heading"><h2>最近的文献</h2><RouterLink to="/library">查看全部 →</RouterLink></div><div v-for="paper in papers" :key="paper.id" class="recent-paper"><div class="paper-thumbnail"><Icon name="Document"/><span>PDF</span></div><div><RouterLink :to="`/papers/${paper.id}`" class="paper-title">{{paper.title}}</RouterLink><div class="metadata"><code>P{{paper.id}}</code><span>{{paper.doi||'DOI 未记录'}}</span></div><div class="tag-row"><el-tag size="small" type="success" effect="plain">已获取全文</el-tag><el-tag v-if="paper.has_analysis" size="small" effect="plain">已分析</el-tag></div></div><RouterLink :to="`/papers/${paper.id}`" class="arrow-button" aria-label="打开论文">↗</RouterLink></div><div v-if="!papers.length" class="quiet-empty">还没有论文，先去检索并收藏。</div></section><section class="panel evidence-intro"><div class="eyebrow">BUILT ON EVIDENCE</div><div class="evidence-visual"><span class="visual-document">研究结论 <i>↗</i></span><span class="connector"/><span class="visual-evidence">E135 <small>原文证据</small></span></div><h2>让引用成为入口。</h2><p>点击结论旁的证据编号，查看论文来源、原文片段与实际页码。</p><p class="note">证据位置可核验，科学结论仍需你的判断。</p><RouterLink to="/library">打开文献库 →</RouterLink></section></div></template>
